from project import check_DNA, read_DNA, translate
import pytest


def test_check_DNA():
    assert check_DNA("sequence.txt") == True
    assert check_DNA("sequence.fasta") == False


def test_translate():
    assert translate("") == ""
    assert translate("") == ""


def test_read_DNA():
    assert read_DNA("sequence.txt") == ""
    assert read_DNA("silent.txt") == ""


